// Funcao de predicao universal executada no navegador
window.predictHeartRisk = function(p) {
    var model = window.HEART_AI_MODEL;
    if (!model) return null;

    // Constrói o vetor com as 24 variáveis clínicas
    // Valores padrao para variaveis secundarias
    var age = Number(p.Age || 50);
    var sex = String(p.Sex).toLowerCase().startsWith('m') ? 1 : 0;
    var chol = Number(p.Cholesterol || 220);
    
    // BP label approximation baseada em pressao sistolica e diastolica
    var sys = Number(p.Systolic || 120);
    var dia = Number(p.Diastolic || 80);
    var bpLabel = Math.min(3900, Math.max(10, Math.round((sys - 90) * 35 + (dia - 60) * 15)));
    
    var hr = Number(p.HeartRate || 75);
    var diabetes = (p.Diabetes === true || p.Diabetes === 1 || p.Diabetes === '1' || p.Diabetes === 'Yes' || p.Diabetes === 'Sim') ? 1 : 0;
    var famHist = (p.FamilyHistory === true || p.FamilyHistory === 1 || p.FamilyHistory === '1' || p.FamilyHistory === 'Yes' || p.FamilyHistory === 'Sim') ? 1 : 0;
    var smoking = (p.Smoking === true || p.Smoking === 1 || p.Smoking === '1' || p.Smoking === 'Yes' || p.Smoking === 'Sim') ? 1 : 0;
    var obesity = (p.Obesity === true || p.Obesity === 1 || p.Obesity === '1' || p.Obesity === 'Yes' || p.Obesity === 'Sim') ? 1 : 0;
    var alcohol = (p.Alcohol === true || p.Alcohol === 1 || p.Alcohol === '1' || p.Alcohol === 'Yes' || p.Alcohol === 'Sim') ? 1 : 0;
    var exercise = Number(p.ExerciseHours || 5.0);
    var diet = Number(p.Diet !== undefined ? p.Diet : 0); // 0=Average, 1=Healthy, 2=Unhealthy
    var prevProblems = Number(p.PreviousProblems || 0);
    var medication = Number(p.Medication || 0);
    var stress = Number(p.Stress || 5);
    var sedentary = Number(p.SedentaryHours || 6.0);
    var income = Number(p.Income || 150000);
    var bmi = Number(p.BMI || 28.0);
    var trig = Number(p.Triglycerides || 400);
    var activeDays = Number(p.ActiveDays || 3);
    var sleep = Number(p.SleepHours || 7);
    var country = 2; // Brasil
    var continent = 5; // South America
    var hemisphere = 1; // Southern

    var rawVector = [
        age, sex, chol, bpLabel, hr, diabetes, famHist, smoking, obesity,
        alcohol, exercise, diet, prevProblems, medication, stress, sedentary,
        income, bmi, trig, activeDays, sleep, country, continent, hemisphere
    ];

    // 1. Normalização com StandardScaler
    var scaled = [];
    for (var i = 0; i < 24; i++) {
        var m = model.scaler_mean[i];
        var s = model.scaler_scale[i];
        scaled.push((rawVector[i] - m) / (s || 1));
    }

    // 2. Inferência com Random Forest (Ensemble de Árvores de Decisão)
    var trees = model.rf_trees;
    var treeProbs = [];
    for (var t = 0; t < trees.length; t++) {
        var cl = trees[t][0];
        var cr = trees[t][1];
        var f = trees[t][2];
        var th = trees[t][3];
        var v = trees[t][4];
        
        var node = 0;
        while (cl[node] !== -1) {
            var featIdx = f[node];
            var threshold = th[node];
            if (scaled[featIdx] <= threshold) {
                node = cl[node];
            } else {
                node = cr[node];
            }
        }
        treeProbs.push(v[node]);
    }

    var avgRfProb = treeProbs.reduce(function(a, b){ return a + b; }, 0) / treeProbs.length;

    // 3. Inferência com Regressão Logística
    var lrScore = model.lr_intercept;
    for (var j = 0; j < 24; j++) {
        lrScore += model.lr_coef[j] * scaled[j];
    }
    var lrProb = 1 / (1 + Math.exp(-lrScore));

    // Combinação ponderada dos modelos
    var finalProb = (avgRfProb * 0.7) + (lrProb * 0.3);

    // Identificação de fatores clínicos de risco
    var riskFactors = [];
    if (chol >= 240) riskFactors.push('Colesterol elevado (' + chol + ' mg/dL)');
    if (sys >= 135) riskFactors.push('Pressão sistólica alta (' + sys + ' mmHg)');
    if (smoking === 1) riskFactors.push('Tabagismo ativo');
    if (diabetes === 1) riskFactors.push('Diabetes diagnosticado');
    if (obesity === 1 || bmi >= 30) riskFactors.push('Obesidade / IMC elevado (' + bmi.toFixed(1) + ')');
    if (famHist === 1) riskFactors.push('Histórico familiar cardiovascular');
    if (stress >= 7) riskFactors.push('Alto nível de estresse (' + stress + '/10)');
    if (sedentary >= 8) riskFactors.push('Sedentarismo acentuado (' + sedentary + 'h/dia)');

    var level = 'Baixo';
    var badgeColor = 'var(--green)';
    if (finalProb >= 0.55) {
        level = 'Alto Risco';
        badgeColor = 'var(--red)';
    } else if (finalProb >= 0.38) {
        level = 'Risco Moderado';
        badgeColor = 'var(--orange)';
    } else {
        level = 'Baixo Risco';
        badgeColor = 'var(--green)';
    }

    return {
        probability: finalProb,
        percentage: (finalProb * 100).toFixed(1),
        level: level,
        color: badgeColor,
        factors: riskFactors,
        rfProb: (avgRfProb * 100).toFixed(1),
        lrProb: (lrProb * 100).toFixed(1)
    };
};
